import { createClient } from "@/lib/supabase/server";
import { requireViewer } from "@/lib/auth";
import { getCompanyAccess } from "@/lib/company";
import { createWorkspaceInvite,updateMemberAccess } from "@/app/app/actions";
import { CopyLink } from "@/components/copy-link";
import { UserPlus } from "lucide-react";
type Directory={canInvite:boolean;members:Array<{id:string;user_id:string;name:string;role:string;status:string;department_id:string|null}>;departments:Array<{id:string;name:string;head_user_id:string|null}>;invitations:Array<{id:string;email:string;role:string;expires_at:string}>};

export async function CompanyPeople({invite,message}:{invite?:string;message?:string}) {
 const viewer=await requireViewer(),db=await createClient(),access=await getCompanyAccess(viewer.organisationId);
 const result=await db.rpc("team_onboarding_directory",{workspace:viewer.organisationId});
 if(result.error)throw new Error("Your permitted team directory could not be loaded.");
 const directory=result.data as Directory,admin=access.people>=2&&access.access>=2;
 return <>{message&&<p className="form-message" role="status">{message}</p>}{invite&&<div className="copy-row"><div className="code-box">{invite}</div><CopyLink value={invite}/></div>}<div className="row-list">{directory.members.map(m=><div className="row-item member-row" key={m.id}><div><h3>{m.name||"New member"}</h3><p>{directory.departments.find(d=>d.id===m.department_id)?.name||"Department not assigned"}</p><span className="chip">{m.role}</span> <span className="chip">{m.status}</span></div>{admin&&m.role!=="owner"&&m.user_id!==viewer.id&&(m.role!=="manager"||viewer.role==="owner")&&<form className="access-form" action={updateMemberAccess}><input type="hidden" name="membershipId" value={m.id}/><select name="role" defaultValue={m.role} aria-label={`Working access for ${m.name}`}><option value="participant">Employee</option><option value="hr">HR and People</option><option value="consultant">Consultant</option>{viewer.role==="owner"&&<option value="manager">Manager</option>}</select><select name="status" defaultValue={m.status} aria-label={`Account status for ${m.name}`}><option value="active">Active</option><option value="suspended">Suspended</option></select><button className="button button-quiet">Update</button></form>}</div>)}</div>{directory.canInvite&&<section className="company-section"><h2>Add a team member</h2><form action={createWorkspaceInvite} className="stack-form company-profile-form"><div className="company-field-grid"><label>Work email<input name="email" type="email" required/></label><label>Working access<select name="role" defaultValue="participant"><option value="participant">Employee</option>{viewer.role==="owner"&&<><option value="manager">Manager</option><option value="hr">HR and People</option><option value="consultant">Consultant</option></>}</select></label><label>Department<select name="departmentId" required={viewer.role!=="owner"&&viewer.role!=="hr"&&access.people<2}><option value="">Not assigned yet</option>{directory.departments.map(d=><option value={d.id} key={d.id}>{d.name}</option>)}</select></label><label>Reports to<select name="managerId"><option value="">Department head / assign later</option>{directory.members.filter(m=>m.status==="active"&&m.role!=="consultant").map(m=><option value={m.user_id} key={m.id}>{m.name}</option>)}</select></label></div><button className="button button-primary"><UserPlus size={16}/>Create invitation</button></form></section>}<section className="company-section"><h2>Pending invitations</h2>{directory.invitations.length?directory.invitations.map(i=><div className="row-item" key={i.id}><div><h3>{i.email}</h3><p>{i.role} / Expires {new Date(i.expires_at).toLocaleDateString("en-GB")}</p></div></div>):<p>No pending invitations.</p>}</section></>;
}
